/// <summary>
/// Extension of class VendAccruedPurchasesDP
/// </summary>
[ExtensionOf(classStr(VendAccruedPurchasesDP))]
final class METVendAccruedPurchasesDP_Extension
{
}

Method.Source:
/// <summary>
/// executing the report business logic
/// </summary>
public void processReport()
{
    next processReport(); // Call base logic

    // Additional updates
    this.updateProductReceiptId();
    this.updateBuyFromVendor();
    this.updateCatchWeightFields();
    this.updatePackSize();
    this.updateWeight();
    this.updateGSTAmount();
    this.updateCompany();
}

/// <summary>
/// update the product receipt 
/// </summary>
private void updateProductReceiptId()
{
    VendPackingSlipJour     vendPackingSlipJour;
    VendPackingSlipTrans    vendPackingSlipTrans;
    VendAccruedPurchasesTmp vendAccruedPurchasesTmp = this.getVendAccruedPurchasesTmp();

    vendAccruedPurchasesTmp.ttsbegin();
    update_recordSet vendAccruedPurchasesTmp
    setting METPackingSlipId = vendPackingSlipJour.PackingSlipId
        join vendPackingSlipTrans
            where vendPackingSlipTrans.sourceDocumentline == vendAccruedPurchasesTmp.PackingSlipSourceDocumentLine
        join vendPackingSlipJour
            where vendPackingSlipJour.RecId == vendPackingSlipTrans.VendPackingSlipJour;
    vendAccruedPurchasesTmp.ttscommit();
}

/// <summary>
/// update the vendor and name
/// </summary>
private void updateBuyFromVendor()
{
    PurchTable              purchTable;
    VendTable               vendTable;
    DirPartyTable           dirPartyTable;
    VendAccruedPurchasesTmp vendAccruedPurchasesTmp = this.getVendAccruedPurchasesTmp();

    vendAccruedPurchasesTmp.ttsbegin();
    update_recordSet vendAccruedPurchasesTmp
    setting METOrderAccount = purchTable.OrderAccount, 
        METPurchName = dirPartyTable.Name
        join purchTable
            where purchTable.PurchId == vendAccruedPurchasesTmp.ReferenceId
        join vendTable
            where vendTable.AccountNum == purchTable.OrderAccount
        join dirPartyTable
            where dirPartyTable.RecId == vendTable.Party;
    vendAccruedPurchasesTmp.ttscommit();
}

/// <summary>
/// update the catchweight
/// </summary>
private void updateCatchWeightFields()
{
    PdsCatchWeightItem      pdsCatchWeightItem;
    VendPackingSlipTrans    vendPackingSlipTrans;
    PurchLine               purchLine;
    VendAccruedPurchasesTmp vendAccruedPurchasesTmp = this.getVendAccruedPurchasesTmp();

    vendAccruedPurchasesTmp.ttsbegin();
    update_recordSet vendAccruedPurchasesTmp
    setting METPdsCWQty = vendPackingSlipTrans.PdsCWQty,
           METPdsCWUnitId = pdsCatchWeightItem.PdsCWUnitId
        join vendPackingSlipTrans
            where vendPackingSlipTrans.SourceDocumentLine == vendAccruedPurchasesTmp.PackingSlipSourceDocumentLine
        join purchLine
            where purchLine.PurchId == vendPackingSlipTrans.OrigPurchid
                && purchLine.LineNumber == vendPackingSlipTrans.PurchaseLineLineNumber
                && purchLine.ItemId == vendAccruedPurchasesTmp.ItemId
        join pdsCatchWeightItem
            where pdsCatchWeightItem.ItemId == purchLine.ItemId;
    vendAccruedPurchasesTmp.ttscommit();
}

/// <summary>
/// update the pack
/// </summary>
private void updatePackSize()
{
    VendPackingSlipTrans    vendPackingSlipTrans;
    UnitOfMeasureConversion unitOfMeasureConversion;
    InventTable             inventTable;
    VendAccruedPurchasesTmp vendAccruedPurchasesTmp = this.getVendAccruedPurchasesTmp();

    vendAccruedPurchasesTmp.ttsbegin();
    while select forupdate vendAccruedPurchasesTmp
    {
        select firstonly PurchUnit, ItemId from vendPackingSlipTrans
            where vendPackingSlipTrans.sourceDocumentline == vendAccruedPurchasesTmp.PackingSlipSourceDocumentLine
            join Product from inventTable
                where inventTable.ItemId == vendPackingSlipTrans.ItemId;

        select firstonly Factor from unitOfMeasureConversion
            where unitOfMeasureConversion.Product == inventTable.Product &&
                  unitOfMeasureConversion.FromUnitOfMeasure == UnitOfMeasure::unitOfMeasureIdBySymbol(vendPackingSlipTrans.PurchUnit)  &&
                  unitOfMeasureConversion.ToUnitOfMeasure == UnitOfMeasure::unitOfMeasureIdBySymbol("@MET:EA");

        vendAccruedPurchasesTmp.METFactor = unitOfMeasureConversion.Factor;
        vendAccruedPurchasesTmp.update();
    }
    vendAccruedPurchasesTmp.ttscommit();
}

/// <summary>
/// update the weight
/// </summary>
private void updateWeight()
{
    VendPackingSlipTrans    vendPackingSlipTrans;
    InventTable             inventTable;
    VendAccruedPurchasesTmp vendAccruedPurchasesTmp = this.getVendAccruedPurchasesTmp();

    vendAccruedPurchasesTmp.ttsbegin();
    update_recordSet vendAccruedPurchasesTmp
        setting METWeight = vendPackingSlipTrans.Qty
            join vendPackingSlipTrans
                where vendPackingSlipTrans.sourceDocumentline == vendAccruedPurchasesTmp.PackingSlipSourceDocumentLine
            join inventTable
                where inventTable.ItemId == vendPackingSlipTrans.ItemId
                    && inventTable.pdsCWItem() == NoYes::Yes;
    vendAccruedPurchasesTmp.ttscommit();
}

/// <summary>
/// update the GSTAmount
/// </summary>
private void updateGSTAmount()
{
    PurchLine               purchLine;
    vendPackingSlipTrans    vendPackingSlipTrans;
    VendAccruedPurchasesTmp vendAccruedPurchasesTmp = this.getVendAccruedPurchasesTmp();

    vendAccruedPurchasesTmp.ttsbegin();
    while select forupdate vendAccruedPurchasesTmp
    {
        select firstonly CurrencyCode, TaxItemGroup, PurchQty, LineAmount, TaxGroup from purchLine
            exists join vendPackingSlipTrans
                where purchLine.PurchId == vendPackingSlipTrans.OrigPurchid
                    && purchLine.LineNumber == vendPackingSlipTrans.PurchaseLineLineNumber
                    && purchLine.ItemId == vendPackingSlipTrans.ItemId
                    && vendPackingSlipTrans.sourceDocumentline == vendAccruedPurchasesTmp.PackingSlipSourceDocumentLine;

        vendAccruedPurchasesTmp.METGSTAmount = Tax::calcTaxAmount(purchLine.TaxGroup,
                                                    purchLine.TaxItemGroup,
                                                    DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                                                    purchLine.CurrencyCode,
                                                    purchLine.LineAmount,
                                                    TaxModuleType::Purch) * vendAccruedPurchasesTmp.Qty/purchLine.PurchQty;
        vendAccruedPurchasesTmp.update();
    }
    vendAccruedPurchasesTmp.ttscommit();
}

/// <summary>
/// update the company
/// </summary>
private void updateCompany()
{
    VendPackingSlipTrans    vendPackingSlipTrans;
    VendAccruedPurchasesTmp vendAccruedPurchasesTmp = this.getVendAccruedPurchasesTmp();

    vendAccruedPurchasesTmp.ttsbegin();
    update_recordSet vendAccruedPurchasesTmp
        setting METCompany = vendPackingSlipTrans.DataAreaId
            join vendPackingSlipTrans
                where vendPackingSlipTrans.sourceDocumentline == vendAccruedPurchasesTmp.PackingSlipSourceDocumentLine;
    vendAccruedPurchasesTmp.ttscommit();
}
